INSERT IGNORE INTO TriviaPregunta (Clave, Idioma, Texto, OpcionA, OpcionB, OpcionC, OpcionD, Correcta, Explicacion) VALUES
('edad_cachorro_solido', 'es', '¿A qué edad suelen empezar a comer alimento sólido los cachorros?', 'Entre las 3 y 4 semanas', 'Al nacer', 'Recién a los 6 meses', 'Al año', 'A', 'Antes lloran por la teta, pero ya pueden ir probando papilla blanda.'),
('edad_cachorro_solido', 'en', 'At what age do puppies usually start eating solid food?', 'Around 3 to 4 weeks old', 'Right at birth', 'Not until 6 months', 'At one year old', 'A', 'Before that they still need their mother\'s milk, but they can start trying soft food.'),
('gato_ronroneo', 'es', '¿El ronroneo de un gato siempre significa que está contento?', 'No, también puede ronronear cuando está estresado o dolorido', 'Sí, siempre es de felicidad', 'No, sólo lo hacen los gatitos', 'Sí, y sólo cuando comen', 'A', 'Es un mecanismo de auto-calma que usan en varias situaciones, no sólo cuando están felices.'),
('gato_ronroneo', 'en', 'Does a cat\'s purr always mean it\'s happy?', 'No, cats can also purr when stressed or in pain', 'Yes, it always means happiness', 'No, only kittens purr', 'Yes, but only while eating', 'A', 'Purring is a self-soothing mechanism used in many situations, not only happiness.'),
('perro_uvas', 'es', '¿Qué fruta es tóxica para los perros y puede dañarles los riñones?', 'Las uvas y las pasas', 'La banana', 'La manzana sin semillas', 'La sandía', 'A', 'Incluso en poca cantidad pueden causar insuficiencia renal aguda.'),
('perro_uvas', 'en', 'Which fruit is toxic to dogs and can damage their kidneys?', 'Grapes and raisins', 'Bananas', 'Apples without seeds', 'Watermelon', 'A', 'Even a small amount can cause acute kidney failure.'),
('gato_cola_lenguaje', 'es', 'Si un gato mueve la cola rápido de lado a lado, ¿qué suele indicar?', 'Irritación o que está por atacar', 'Que quiere upa', 'Que tiene sueño', 'Que tiene hambre', 'A', 'A diferencia del perro, en el gato ese movimiento suele ser una señal de alerta.'),
('gato_cola_lenguaje', 'en', 'If a cat swishes its tail quickly side to side, what does it usually mean?', 'Irritation or that it\'s about to attack', 'That it wants to be picked up', 'That it\'s sleepy', 'That it\'s hungry', 'A', 'Unlike dogs, that motion in cats is usually a warning sign.'),
('perro_jadeo_calor', 'es', '¿Por qué jadean los perros cuando tienen calor?', 'Porque no transpiran por la piel como las personas', 'Porque están nerviosos siempre', 'Porque tienen sed exclusivamente', 'Porque están por vomitar', 'A', 'Regulan la temperatura sobre todo jadeando y transpirando por las almohadillas.'),
('perro_jadeo_calor', 'en', 'Why do dogs pant when they\'re hot?', 'Because they don\'t sweat through their skin like people do', 'Because they\'re always nervous', 'Only because they\'re thirsty', 'Because they\'re about to vomit', 'A', 'They regulate temperature mainly by panting and sweating through their paw pads.'),
('conejo_dientes', 'es', '¿Por qué los conejos necesitan roer todo el tiempo?', 'Sus dientes crecen sin parar durante toda la vida', 'Por aburrimiento nada más', 'Para afilar las uñas', 'Porque les pica la boca', 'A', 'Si no desgastan los dientes royendo, se les pueden crecer de más y lastimarlos.'),
('conejo_dientes', 'en', 'Why do rabbits need to gnaw all the time?', 'Their teeth grow continuously their whole life', 'Just out of boredom', 'To sharpen their claws', 'Because their mouth itches', 'A', 'If they don\'t wear their teeth down by gnawing, they can overgrow and hurt them.'),
('perro_lenguaje_bostezo', 'es', 'En perros, ¿qué puede significar un bostezo fuera de contexto (sin sueño)?', 'Una señal de estrés o incomodidad', 'Que tiene hambre', 'Que está por ladrar', 'Que quiere jugar a la pelota', 'A', 'Es una de las llamadas \"señales de calma\" que usan para autorregularse.'),
('perro_lenguaje_bostezo', 'en', 'In dogs, what can a yawn out of context (not sleepy) mean?', 'A sign of stress or discomfort', 'That it\'s hungry', 'That it\'s about to bark', 'That it wants to play fetch', 'A', 'It\'s one of the so-called \"calming signals\" dogs use to self-regulate.'),
('gato_arenero_cantidad', 'es', 'Si tenés 2 gatos, ¿cuántos areneros se recomiendan como mínimo?', 'Tres (uno por gato más uno extra)', 'Uno solo alcanza', 'Dos, uno por gato', 'Ninguno si salen al patio', 'A', 'La regla general es \"N+1\" areneros para evitar peleas por territorio.'),
('gato_arenero_cantidad', 'en', 'If you have 2 cats, how many litter boxes are recommended at minimum?', 'Three (one per cat plus one extra)', 'Just one is enough', 'Two, one per cat', 'None if they go outside', 'A', 'The general rule is \"N+1\" litter boxes to avoid territorial conflicts.'),
('perro_cebolla_ajo', 'es', '¿La cebolla y el ajo son seguros para los perros?', 'No, pueden dañarles los glóbulos rojos', 'Sí, en cualquier cantidad', 'Sólo la cebolla es peligrosa, el ajo no', 'Sí, si están bien cocidos', 'A', 'Contienen compuestos que pueden causar anemia hemolítica en perros y gatos.'),
('perro_cebolla_ajo', 'en', 'Are onion and garlic safe for dogs?', 'No, they can damage their red blood cells', 'Yes, in any amount', 'Only onion is dangerous, not garlic', 'Yes, if well cooked', 'A', 'They contain compounds that can cause hemolytic anemia in dogs and cats.'),
('gato_esterilizacion_edad', 'es', '¿A qué edad suele recomendarse esterilizar a un gato?', 'Alrededor de los 4-6 meses', 'Recién pasado el año', 'A las 2 semanas de vida', 'Nunca, es innecesario', 'A', 'Cuanto antes, menor el riesgo de ciertos tumores y de camadas no deseadas.'),
('gato_esterilizacion_edad', 'en', 'At what age is it usually recommended to spay/neuter a cat?', 'Around 4-6 months old', 'Only after turning one year old', 'At 2 weeks of age', 'Never, it\'s unnecessary', 'A', 'The earlier it\'s done, the lower the risk of certain tumors and unwanted litters.'),
('perro_agresion_dolor', 'es', 'Un perro dócil que de repente se pone agresivo al tocarlo, ¿qué puede indicar?', 'Que puede estar sintiendo dolor', 'Que se volvió malo de golpe', 'Que quiere jugar más fuerte', 'Que reconoció a un extraño', 'A', 'Un cambio de comportamiento brusco es motivo para consultar al veterinario.'),
('perro_agresion_dolor', 'en', 'A gentle dog that suddenly becomes aggressive when touched — what might that indicate?', 'That it may be in pain', 'That it suddenly turned mean', 'That it wants to play rougher', 'That it recognized a stranger', 'A', 'A sudden behavior change is a reason to see a veterinarian.'),
('gato_agua_fuente', 'es', '¿Por qué muchos gatos prefieren tomar agua corriente (de una canilla o fuente)?', 'Por instinto: en la naturaleza el agua quieta puede estar contaminada', 'Porque no les gusta el agua en general', 'Porque el agua quieta tiene mal sabor siempre', 'Es sólo una moda sin motivo', 'A', 'Es un instinto heredado de sus ancestros salvajes.'),
('gato_agua_fuente', 'en', 'Why do many cats prefer running water (from a tap or fountain)?', 'Instinct: in the wild, still water can be contaminated', 'Because they dislike water in general', 'Because still water always tastes bad', 'It\'s just a random preference', 'A', 'It\'s an instinct inherited from their wild ancestors.'),
('perro_paseo_diario', 'es', '¿Por qué es importante pasear a un perro todos los días, más allá de hacer sus necesidades?', 'Por estimulación mental y desgaste de energía', 'Sólo para que tome sol', 'Para que socialice con autos', 'No es realmente necesario si tiene patio', 'A', 'Un perro sin estímulo mental puede desarrollar ansiedad o comportamientos destructivos.'),
('perro_paseo_diario', 'en', 'Why is it important to walk a dog every day, beyond bathroom breaks?', 'For mental stimulation and burning energy', 'Just to get some sun', 'To socialize with cars', 'It\'s not really necessary if it has a yard', 'A', 'A dog without mental stimulation can develop anxiety or destructive behaviors.'),
('gato_vomito_bola_pelo', 'es', '¿Qué son las \"bolas de pelo\" que a veces vomitan los gatos?', 'Pelo acumulado del acicalado que no pudo digerir', 'Un signo de que están envenenados', 'Comida que no les gustó', 'Parásitos intestinales', 'A', 'Se forman por el pelo que tragan al lamerse; en exceso pueden necesitar ayuda veterinaria.'),
('gato_vomito_bola_pelo', 'en', 'What are the \"hairballs\" cats sometimes vomit up?', 'Hair from grooming that they couldn\'t digest', 'A sign they\'ve been poisoned', 'Food they didn\'t like', 'Intestinal parasites', 'A', 'They form from hair swallowed while grooming; in excess they may need veterinary help.'),
('perro_temperatura_normal', 'es', '¿Cuál es, aproximadamente, la temperatura corporal normal de un perro?', 'Entre 38 y 39 °C', 'Igual que la de una persona, 36.5 °C', 'Entre 42 y 44 °C', 'Entre 30 y 33 °C', 'A', 'Es más alta que la de los humanos; por eso lo que a nosotros nos da fiebre a ellos no.'),
('perro_temperatura_normal', 'en', 'What is a dog\'s approximate normal body temperature?', 'Between 38 and 39 °C (about 101-102°F)', 'The same as a human, 36.5 °C', 'Between 42 and 44 °C', 'Between 30 and 33 °C', 'A', 'It\'s higher than a human\'s, which is why what gives us a fever doesn\'t affect them the same way.'),
('gato_juego_caza', 'es', '¿Por qué es bueno simular \"cacería\" con juguetes para un gato de interior?', 'Satisface su instinto natural de cazador', 'Sólo sirve para gastar el juguete', 'Los gatos de interior no necesitan jugar', 'Es sólo para gatitos, no adultos', 'A', 'Aunque coman de un plato, mantienen intacto el instinto de caza toda la vida.'),
('gato_juego_caza', 'en', 'Why is it good to simulate \"hunting\" with toys for an indoor cat?', 'It satisfies their natural hunting instinct', 'It\'s just to wear out the toy', 'Indoor cats don\'t need to play', 'It\'s only for kittens, not adults', 'A', 'Even though they eat from a bowl, their hunting instinct stays with them for life.'),
('perro_castigos_fisicos', 'es', '¿Por qué se recomienda no usar castigos físicos para educar a un perro?', 'Puede generar miedo y agresividad, sin enseñar realmente', 'Porque es ilegal en todos los países', 'Porque no sienten dolor', 'Porque prefieren el silencio', 'A', 'El refuerzo positivo es más efectivo y no rompe el vínculo de confianza.'),
('perro_castigos_fisicos', 'en', 'Why is it recommended not to use physical punishment to train a dog?', 'It can cause fear and aggression without really teaching anything', 'Because it\'s illegal in every country', 'Because dogs don\'t feel pain', 'Because dogs prefer silence', 'A', 'Positive reinforcement is more effective and doesn\'t break the bond of trust.'),
('gato_esconderse_enfermo', 'es', '¿Por qué un gato enfermo tiende a esconderse?', 'Es un instinto de supervivencia: en la naturaleza, mostrar debilidad los hace presa fácil', 'Porque se avergüenza', 'Porque no le gusta la casa', 'Porque busca más comida', 'A', 'Por eso hay que prestar atención a cambios de comportamiento, no sólo síntomas visibles.'),
('gato_esconderse_enfermo', 'en', 'Why does a sick cat tend to hide?', 'It\'s a survival instinct: in the wild, showing weakness makes them easy prey', 'Because it\'s embarrassed', 'Because it doesn\'t like the house', 'Because it\'s looking for more food', 'A', 'That\'s why it\'s important to notice behavior changes, not just visible symptoms.'),
('perro_edad_humana_mito', 'es', '¿Es correcto que \"1 año de perro equivale a 7 años humanos\" siempre?', 'No, depende de la raza y el tamaño, y no es lineal', 'Sí, es una regla exacta', 'Sí, pero sólo en perros grandes', 'No, en realidad es al revés', 'A', 'Los perros maduran mucho más rápido los primeros años y luego se estabiliza distinto según el tamaño.'),
('perro_edad_humana_mito', 'en', 'Is it correct that \"1 dog year equals 7 human years\" always?', 'No, it depends on breed and size, and it\'s not linear', 'Yes, it\'s an exact rule', 'Yes, but only for large dogs', 'No, it\'s actually the reverse', 'A', 'Dogs mature much faster in their first years, then the rate changes differently by size.'),
('gato_uñas_rascador', 'es', '¿Por qué los gatos necesitan rascar superficies?', 'Para marcar territorio y desgastar las uñas', 'Sólo para molestar', 'Porque les pican las patas', 'Para afilar los dientes', 'A', 'Las glándulas de las patas dejan feromonas al rascar, es una forma de comunicación.'),
('gato_uñas_rascador', 'en', 'Why do cats need to scratch surfaces?', 'To mark territory and wear down their claws', 'Just to be annoying', 'Because their paws itch', 'To sharpen their teeth', 'A', 'Glands in their paws leave pheromones when scratching — it\'s a form of communication.'),
('perro_lengua_termorregulacion', 'es', 'Además de jadear, ¿qué otra zona usan los perros para liberar calor?', 'Las almohadillas de las patas', 'Las orejas exclusivamente', 'La cola', 'El hocico seco', 'A', 'Transpiran levemente por las almohadillas, aunque el jadeo es el mecanismo principal.'),
('perro_lengua_termorregulacion', 'en', 'Besides panting, what other area do dogs use to release heat?', 'The paw pads', 'Only the ears', 'The tail', 'The dry nose', 'A', 'They sweat lightly through their paw pads, though panting is the main mechanism.'),
('gato_leche_cachorro', 'es', '¿Pueden los gatitos recién nacidos tomar leche de vaca en vez de la de su madre?', 'No, necesitan leche maternizada específica para gatos', 'Sí, sin ningún problema', 'Sí, pero diluida con agua', 'Sí, si es leche descremada', 'A', 'La leche de vaca no tiene los nutrientes que necesitan y puede darles diarrea.'),
('gato_leche_cachorro', 'en', 'Can newborn kittens drink cow\'s milk instead of their mother\'s?', 'No, they need special kitten milk replacer formula', 'Yes, with no problem at all', 'Yes, but diluted with water', 'Yes, if it\'s skim milk', 'A', 'Cow\'s milk lacks the nutrients they need and can cause diarrhea.'),
('perro_socializacion_cachorro', 'es', '¿Cuál es el período más importante para socializar a un cachorro?', 'Entre las 3 y las 14 semanas de vida', 'Después del año de edad', 'Recién nacido, en la primera semana', 'No hay un período especial', 'A', 'Es la ventana en la que aprende, con menos miedo, a relacionarse con el mundo.'),
('perro_socializacion_cachorro', 'en', 'What is the most important period to socialize a puppy?', 'Between 3 and 14 weeks of age', 'After turning one year old', 'Right at birth, in the first week', 'There is no special period', 'A', 'It\'s the window where they learn to relate to the world with less fear.'),
('gato_comportamiento_amasar', 'es', '¿Por qué los gatos \"amasan\" con las patas delanteras sobre mantas o personas?', 'Es un comportamiento heredado de cuando mamaban de chicos', 'Es un signo de agresividad', 'Buscan comida escondida', 'Sólo lo hacen los gatos machos', 'A', 'De gatitos amasaban a la madre para estimular la producción de leche.'),
('gato_comportamiento_amasar', 'en', 'Why do cats \"knead\" with their front paws on blankets or people?', 'It\'s a behavior inherited from nursing as kittens', 'It\'s a sign of aggression', 'They\'re looking for hidden food', 'Only male cats do it', 'A', 'As kittens they kneaded their mother to stimulate milk production.'),
('perro_alimentos_prohibidos_xilitol', 'es', '¿Qué edulcorante, presente en chicles y golosinas sin azúcar, es muy tóxico para perros?', 'El xilitol', 'El azúcar común', 'La miel', 'La sacarina', 'A', 'Puede provocarles una baja brusca de azúcar en sangre y daño hepático.'),
('perro_alimentos_prohibidos_xilitol', 'en', 'What sweetener, found in sugar-free gum and candy, is highly toxic to dogs?', 'Xylitol', 'Regular sugar', 'Honey', 'Saccharin', 'A', 'It can cause a sudden drop in blood sugar and liver damage.'),
('gato_ojo_tercer_parpado', 'es', '¿Qué puede indicar que se vea el \"tercer párpado\" (membrana blanca) en el ojo de un gato?', 'Puede ser señal de enfermedad o malestar general', 'Es completamente normal y no significa nada', 'Que está por dormir la siesta', 'Que tiene mucha luz en los ojos', 'A', 'En un gato sano casi no se ve; si queda visible conviene consultar al veterinario.'),
('gato_ojo_tercer_parpado', 'en', 'What can it mean if a cat\'s \"third eyelid\" (white membrane) is visible?', 'It can be a sign of illness or general discomfort', 'It\'s completely normal and means nothing', 'That it\'s about to take a nap', 'That there\'s too much light in its eyes', 'A', 'In a healthy cat it\'s barely visible; if it stays visible, see a veterinarian.'),
('perro_comida_huesos_cocidos', 'es', '¿Por qué no se les debe dar huesos cocidos a los perros?', 'Se astillan fácil y pueden perforar el intestino', 'Porque no les gusta el sabor', 'Porque engordan mucho', 'Porque manchan los dientes', 'A', 'Los huesos crudos son distintos, pero los cocidos pierden flexibilidad y se rompen en esquirlas.'),
('perro_comida_huesos_cocidos', 'en', 'Why shouldn\'t dogs be given cooked bones?', 'They splinter easily and can puncture the intestine', 'Because they don\'t like the taste', 'Because they cause a lot of weight gain', 'Because they stain the teeth', 'A', 'Raw bones are different, but cooked ones lose flexibility and break into sharp shards.'),
('gato_arenero_ubicacion', 'es', '¿Dónde NO conviene ubicar el arenero de un gato?', 'Al lado de su plato de comida', 'En un lugar tranquilo de la casa', 'Lejos del paso de gente', 'En un ambiente ventilado', 'A', 'Los gatos evitan por instinto hacer sus necesidades cerca de donde comen.'),
('gato_arenero_ubicacion', 'en', 'Where should a cat\'s litter box NOT be placed?', 'Right next to its food bowl', 'In a quiet spot in the house', 'Away from foot traffic', 'In a well-ventilated area', 'A', 'Cats instinctively avoid eliminating near where they eat.'),
('perro_ansiedad_separacion', 'es', '¿Qué es la \"ansiedad por separación\" en perros?', 'Estrés y comportamientos destructivos cuando se quedan solos', 'Miedo a los truenos únicamente', 'Rechazo a comer alimento nuevo', 'Ladrar sólo de noche', 'A', 'Puede incluir destrozos, ladridos excesivos o hacer sus necesidades dentro de la casa.'),
('perro_ansiedad_separacion', 'en', 'What is \"separation anxiety\" in dogs?', 'Stress and destructive behaviors when left alone', 'Fear of thunder only', 'Refusing to eat new food', 'Barking only at night', 'A', 'It can include destruction, excessive barking, or accidents indoors.'),
('gato_esterilizacion_mitos', 'es', '¿Es cierto que esterilizar a una gata la hace \"más gorda y vaga\" para siempre?', 'No necesariamente: depende de la alimentación y el ejercicio, no de la cirugía en sí', 'Sí, es un efecto inevitable', 'Sí, pero sólo en gatos machos', 'No, en realidad las hace hiperactivas', 'A', 'El aumento de peso se controla ajustando porciones y manteniendo el juego diario.'),
('gato_esterilizacion_mitos', 'en', 'Is it true that spaying a cat makes her \"fat and lazy\" forever?', 'Not necessarily: it depends on diet and exercise, not the surgery itself', 'Yes, it\'s an unavoidable effect', 'Yes, but only in male cats', 'No, it actually makes them hyperactive', 'A', 'Weight gain is managed by adjusting portions and keeping up daily play.'),
('perro_señales_calma_lamerse', 'es', 'Cuando un perro se lame el hocico repetidamente sin comida cerca, ¿qué puede indicar?', 'Es una señal de calma: está algo incómodo o nervioso', 'Que tiene mucha sed', 'Que está por vomitar siempre', 'Que quiere comer', 'A', 'Es una de las llamadas \"señales de calma\" que usan para bajar tensión.'),
('perro_señales_calma_lamerse', 'en', 'When a dog repeatedly licks its lips with no food nearby, what can that mean?', 'It\'s a calming signal: it feels somewhat uncomfortable or nervous', 'That it\'s very thirsty', 'That it\'s always about to vomit', 'That it wants to eat', 'A', 'It\'s one of the \"calming signals\" dogs use to reduce tension.'),
('gato_vacunas_esenciales', 'es', '¿Qué enfermedad viral grave previene la vacuna triple felina?', 'Entre otras, la panleucopenia felina', 'El resfrío común', 'La rabia únicamente', 'Los parásitos intestinales', 'A', 'La panleucopenia es muy contagiosa y puede ser mortal, sobre todo en gatitos.'),
('gato_vacunas_esenciales', 'en', 'What serious viral disease does the feline triple vaccine help prevent?', 'Among others, feline panleukopenia', 'The common cold', 'Rabies only', 'Intestinal parasites', 'A', 'Panleukopenia is highly contagious and can be fatal, especially in kittens.'),
('perro_alimentacion_porciones', 'es', '¿Qué factor NO debería determinar cuánto alimento darle a un perro por día?', 'Lo que \"sobró\" de la comida familiar', 'Su peso y nivel de actividad', 'La recomendación del veterinario', 'El tipo de alimento balanceado', 'A', 'Las sobras humanas suelen desbalancear la dieta y favorecer el sobrepeso.'),
('perro_alimentacion_porciones', 'en', 'Which factor should NOT determine how much food to give a dog per day?', 'Leftovers from the family meal', 'Its weight and activity level', 'The veterinarian\'s recommendation', 'The type of kibble/balanced food', 'A', 'Human leftovers tend to unbalance the diet and encourage overweight.'),
('gato_estres_cambios', 'es', '¿Por qué los gatos suelen estresarse tanto con cambios en la casa (mudanza, muebles nuevos)?', 'Son animales muy territoriales y dependen de rutinas y olores conocidos', 'No les afecta en absoluto', 'Sólo les molesta el ruido de la mudanza', 'Prefieren siempre lo nuevo', 'A', 'Reconstruir su \"mapa\" de territorio y olores les lleva tiempo y genera ansiedad.'),
('gato_estres_cambios', 'en', 'Why do cats often get so stressed by changes at home (moving, new furniture)?', 'They are very territorial and rely on routines and familiar scents', 'It doesn\'t affect them at all', 'Only the noise of moving bothers them', 'They always prefer new things', 'A', 'Rebuilding their \"map\" of territory and scents takes time and causes anxiety.'),
('perro_juguetes_seguros', 'es', '¿Qué riesgo hay al darle a un perro un juguete demasiado chico para su tamaño?', 'Puede tragárselo y asfixiarse', 'Ninguno, cuanto más chico mejor', 'Se le puede caer un diente', 'Le da menos ganas de jugar', 'A', 'El juguete debe ser proporcional a la boca del perro para evitar atragantamientos.'),
('perro_juguetes_seguros', 'en', 'What\'s the risk of giving a dog a toy that\'s too small for its size?', 'It could swallow it and choke', 'None, smaller is always better', 'It could lose a tooth', 'It makes them less interested in playing', 'A', 'The toy should be sized to the dog\'s mouth to avoid choking hazards.'),
('gato_comunicacion_maullido_adulto', 'es', '¿Es cierto que los gatos adultos maúllan principalmente para comunicarse entre ellos?', 'No, entre gatos adultos usan más el lenguaje corporal; el maullido es sobre todo para comunicarse con humanos', 'Sí, es su única forma de comunicación', 'No, los gatos adultos no maúllan nunca', 'Sí, y dejan de hacerlo con las personas', 'A', 'Los gatitos maúllan a la madre, pero de adultos \"aprenden\" a maullarle a las personas.'),
('gato_comunicacion_maullido_adulto', 'en', 'Is it true that adult cats meow mainly to communicate with each other?', 'No, adult cats mostly use body language with each other; meowing is mainly to communicate with humans', 'Yes, it\'s their only form of communication', 'No, adult cats never meow', 'Yes, and they stop doing it with people', 'A', 'Kittens meow to their mother, but as adults they \"learn\" to meow at people.'),
('perro_paseo_correa_arnes', 'es', '¿Por qué muchos veterinarios recomiendan arnés en vez de collar para pasear perros que tiran?', 'Reparte la presión en el pecho y evita dañar la tráquea', 'Porque es más barato', 'Porque así corren más rápido', 'No hay ninguna diferencia real', 'A', 'Un tirón fuerte con collar puede lastimar la garganta, sobre todo en razas pequeñas.'),
('perro_paseo_correa_arnes', 'en', 'Why do many vets recommend a harness instead of a collar for dogs that pull on walks?', 'It spreads pressure across the chest and avoids damaging the trachea', 'Because it\'s cheaper', 'Because it makes them run faster', 'There\'s no real difference', 'A', 'A hard collar pull can injure the throat, especially in small breeds.'),
('gato_temperatura_fiebre', 'es', '¿A partir de qué temperatura aproximada se considera que un gato tiene fiebre?', 'Más de 39.5 °C', 'Más de 37 °C', 'Más de 35 °C', 'No tienen fiebre nunca', 'A', 'La temperatura normal de un gato ronda los 38-39 °C.'),
('gato_temperatura_fiebre', 'en', 'At approximately what temperature is a cat considered to have a fever?', 'Above 39.5 °C (about 103°F)', 'Above 37 °C', 'Above 35 °C', 'Cats never get fever', 'A', 'A cat\'s normal temperature is around 38-39 °C.'),
('perro_mordida_inhibicion', 'es', '¿Qué es la \"inhibición de la mordida\" que aprenden los cachorros jugando entre hermanos?', 'A controlar la fuerza de su mordida para no lastimar', 'A morder más fuerte cuanto más grandes son', 'A no morder absolutamente nada', 'Es un mito, no existe tal cosa', 'A', 'Cuando un cachorro muerde muy fuerte a un hermano, éste chilla y para el juego — así aprenden límites.'),
('perro_mordida_inhibicion', 'en', 'What is \"bite inhibition\" that puppies learn while playing with littermates?', 'Learning to control the force of their bite to avoid hurting others', 'Learning to bite harder as they grow', 'Learning to never bite at all', 'It\'s a myth, it doesn\'t exist', 'A', 'When a puppy bites too hard, its littermate yelps and stops playing — that\'s how they learn limits.'),
